{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "verse": 101,
      "text_ar": "فقال: «ستكون حريتهم لمدة سبعة أيام، لكي ينظروا في خلال سبعة أيام الأمور التي أُخبرتَ بها، وبعد ذلك يُجمعون في مساكنهم».",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 102,
      "text_ar": "فأجبتُ وقلتُ: «إن كنتُ قد وجدتُ نعمةً في عينيك، فأرِني أنا عبدَك أيضاً: هل يستطيع الأبرار في يوم الدينونة أن يشفعوا في الأشرار، أو يتوسلوا إلى العلي من أجلهم،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 103,
      "text_ar": "أو الآباء من أجل الأبناء، أو الأبناء من أجل الآباء، أو الأقرباء من أجل الأقرباء، أو ذوو القربى من أجل أنسبائهم، أو الأصدقاء من أجل أعز الأحباء؟»",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 104,
      "text_ar": "فأجابني وقال: «بما أنك وجدتَ نعمةً في عينيّ، فسأريك هذا أيضاً. إن يوم الدينونة هو يوم فصل، وهو يعلن للجميع خاتمة الحق. فحتى كما أن الآب اليوم لا يرسل ابنه، ولا الابن أباه، ولا السيد عبده، ولا الصديق أعز أحبائه، لكي يفهم عوضاً عنه، أو ينام، أو يأكل، أو يُشفى،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 105,
      "text_ar": "هكذا لن يصلي أحد قط لأحد في ذلك اليوم، ولن يحمل أحد حملاً عن غيره، لأن كل واحد حينئذ سيحمل بره أو إثمه بنفسه».",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 106,
      "text_ar": "فأجبتُ وقلتُ: «كيف نجد الآن أن إبراهيم صلى أولاً من أجل أهل سدوم، وموسى من أجل الآباء الذين خطئوا في البرية،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 107,
      "text_ar": "ويشوع بعده من أجل إسرائيل في أيام عاخان،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 108,
      "text_ar": "وصموئيل في أيام شاول، وداود من أجل الوباء، سليمان من أجل الذين سيشهدون في الهيكل،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 109,
      "text_ar": "وإيليا من أجل الذين نالوا المطر، ومن أجل الميت لكي يحيا،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 110,
      "text_ar": "وحزقيا من أجل الشعب في أيام سنحاريب، وكثيرون غيرهم صلوا من أجل كثيرين؟",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 111,
      "text_ar": "فإن كان الأمر هكذا الآن، حيث قد نما الفساد وازداد الإثم، فقد صلى الأبرار من أجل الأشرار، فلماذا لا يكون الأمر هكذا أيضاً في ذلك اليوم؟»",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 112,
      "text_ar": "فأجابني وقال: «إن هذا الدهر الحاضر ليس هو النهاية، ولا يقيم فيه المجد الكامل بتمام، ولذلك كان القادرون يصلون من أجل الضعفاء.",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 113,
      "text_ar": "ولكن يوم الدينونة سيكون هو نهاية هذا الدهر، وبداية عدم الفساد العتيد، الذي فيه يزول الفساد،",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 114,
      "text_ar": "وتنتهي الإباحة، وينقطع عدم الإيمان، وينمو البر، ويزهر الحق.",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 115,
      "text_ar": "حينئذ لن يستطيع أحد أن يرحم من حُكم عليه في الدينونة، ولا أن يضر من فاز».",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 116,
      "text_ar": "فأجبتُ حينئذ وقلتُ: «هذا هو قولي الأول والأخير: إنه كان خيرًا للأرض لو أنها لم تخلق آدم، أو أنه عندما خُلق مُنع من الخطيئة.",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 117,
      "text_ar": "فأي نفع لكل من هم في هذا الزمان الحاضر أن يعيشوا في حزن، وأن ينتظروا العقاب بعد الموت؟",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 118,
      "text_ar": "آه يا آدم، ماذا فعلتَ؟ فمع أنك أنت الذي خطئتَ، فلم يقع الشر عليك وحدك، بل علينا كلنا نحن النسل الخارج منك.",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 119,
      "text_ar": "فأي نفع لنا إذا وُعدنا بزمان غير مائت، بينما نحن قد صنعنا أعمالاً توجب الموت؟",
      "review_notes_ar": []
    },
    {
      "chapter": 7,
      "verse": 120,
      "text_ar": "وإذا وُعدنا برجاء أبدي، بينما نحن قد فشلنا بغاية البؤس؟»",
      "review_notes_ar": []
    }
  ]
}
